//! The Shared Workbook Revision Log Part, defined in ECMA-376 Part 1, section 12.3.17, and restated
//! in Part 4, section 10.2.17.
//!
//! The module holds its content type, its relationship type, and the load and store of its root,
//! `x:revisions`. `store_strict` needs the `strict` feature and `store_transitional` the
//! `transitional` feature.

use crate::part_root::{self, PartRoot};
use officekit_markup::spreadsheet;
use officekit_packaging::error::PackageError;
use officekit_packaging::package::{OpenOptions, Package};
use officekit_packaging::part_name::PartName;
use officekit_packaging::relationship::RelationshipType;
#[cfg(feature = "strict")]
use officekit_strict::Strict as _;
#[cfg(feature = "transitional")]
use officekit_transitional::Transitional as _;
use officekit_xml::conformance::ConformanceClass;
use officekit_xml::element::Element;
use officekit_xml::error::WriteError;
#[cfg(not(all(feature = "strict", feature = "transitional")))]
use officekit_xml::write::Scope;
#[cfg(any(feature = "strict", feature = "transitional"))]
use officekit_xml::write::WriteOptions;

/// The content type ECMA-376 Part 1 lists for this part.
pub const CONTENT_TYPE: &str =
    "application/vnd.openxmlformats-officedocument.spreadsheetml.revisionLog+xml";

/// The relationship type that names this part, in both classes' spelling: Strict from ECMA-376 Part
/// 1, section 12.3.17, Transitional from Part 4, section 10.2.17.
pub const RELATIONSHIP_TYPE: RelationshipType = RelationshipType::REVISION_LOG;

impl PartRoot for spreadsheet::Revisions {
    const LOCAL_NAME: &'static str = "revisions";

    fn from_tree(root: &Element) -> Result<Self, String> {
        super::check_root(root, 118, Self::LOCAL_NAME)?;
        Ok(spreadsheet::read::revisions(root))
    }

    fn to_tree(&self, class: ConformanceClass) -> Result<Element, WriteError> {
        #[cfg(feature = "strict")]
        let strict = Self::to_strict;
        #[cfg(not(feature = "strict"))]
        let strict = |root: &Self| Ok(shared_tree(root));
        #[cfg(feature = "transitional")]
        let transitional = Self::to_transitional;
        #[cfg(not(feature = "transitional"))]
        let transitional = |root: &Self| Ok(shared_tree(root));
        super::tree_in_class(self, class, strict, transitional)
    }
}

#[cfg(not(all(feature = "strict", feature = "transitional")))]
fn shared_tree(root: &spreadsheet::Revisions) -> Element {
    spreadsheet::write::revisions(root, &mut Scope::default())
}

/// The part's typed root, read from either class.
///
/// # Errors
///
/// The errors of [`part_root::load`].
pub fn load(
    package: &Package,
    name: &PartName,
    options: OpenOptions,
) -> Result<spreadsheet::Revisions, PackageError> {
    part_root::load(package, name, options)
}

/// Store `root` into the part in the Strict class; the part keeps its
/// content type, or takes this module's.
///
/// This function needs the `strict` feature.
///
/// # Errors
///
/// The errors of [`part_root::store`].
#[cfg(feature = "strict")]
pub fn store_strict(
    package: &mut Package,
    name: &PartName,
    root: &spreadsheet::Revisions,
    options: WriteOptions,
) -> Result<(), PackageError> {
    let content_type = package
        .content_type(name)
        .unwrap_or(CONTENT_TYPE)
        .to_owned();
    part_root::store(
        package,
        name,
        &content_type,
        root,
        ConformanceClass::Strict,
        options,
    )
}

/// Store `root` into the part in the Transitional class; the part keeps its
/// content type, or takes this module's.
///
/// This function needs the `transitional` feature.
///
/// # Errors
///
/// The errors of [`part_root::store`].
#[cfg(feature = "transitional")]
pub fn store_transitional(
    package: &mut Package,
    name: &PartName,
    root: &spreadsheet::Revisions,
    options: WriteOptions,
) -> Result<(), PackageError> {
    let content_type = package
        .content_type(name)
        .unwrap_or(CONTENT_TYPE)
        .to_owned();
    part_root::store(
        package,
        name,
        &content_type,
        root,
        ConformanceClass::Transitional,
        options,
    )
}
